window.docContents[194].resolve({"/ISO-80000-3-___-Space-and-Time/#PropertyKindCalculus-Blueprint--ISO-80000-3-___-Space-and-Time":{"contents":"The first part whose quantity-kinds and units are specified here is ISO 80000-3,\nSpace and time. It is a reviewable seed: a few quantity-kinds — length, duration,\narea, volume, speed, and the vector quantity displacement — and a few coherent SI\nunits — the metre, second, square metre, and so on — each carrying its exact\nsource, the part and the printed item designation, as data. Only citation\nlocators (item number, symbol, coherent SI unit name) are\nrecorded; no normative content from the licensed standard is reproduced. This is\nthe pattern each further part will follow, added as a chapter as its coverage\nbecomes available.\n\n\n\n\n\n\n\n\n\n","context":"PropertyKindCalculus Blueprint","header":"10. ISO 80000-3 — Space and Time","id":"/ISO-80000-3-___-Space-and-Time/#PropertyKindCalculus-Blueprint--ISO-80000-3-___-Space-and-Time"}});